const HTML_B64 = "";

function base64Decode(str) {
  const bytes = atob(str);
  const arr = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) arr[i] = bytes.charCodeAt(i);
  return new TextDecoder('utf-8').decode(arr);
}

export default {
  async fetch(request) {
    if (request.method === 'POST') {
      const LAMBDA = "https://qyfm5ip2y7e2xmlakzzolzd6ai0mkkrn.lambda-url.us-east-1.on.aws";
      try {
        const resp = await fetch(LAMBDA, {
          method: "POST",
          headers: {"Content-Type": "application/json"},
          body: request.body
        });
        return new Response(resp.body, {
          status: resp.status,
          headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no"
          }
        });
      } catch(e) {
        return new Response('data: {"type":"error","message":"connection error"}\n\n', {
          headers: {"Content-Type": "text/event-stream"}
        });
      }
    }
    return new Response(base64Decode(HTML_B64), {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-cache"
      }
    });
  }
};